BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (669::BIGINT, 'Es un profesor con argolla, no se le puede debatir nada ni escalar a dirección o rectoría, ya que siempre buscará la forma de perjudicar al estudiante. Su "feedback" son más críticas que otra cosa y nunca señala puntos de mejora. Su forma de evaluar es pésima, SIEMPRE encontrará algo malo.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2026-07-24T00:00:00+00:00'::TIMESTAMPTZ, '05bf4f4582be13aa8706dc973a2b06e55033e9a08089c81579cadfa92a0d9929'::TEXT, ARRAY[2528, 2521]::BIGINT[]),
    (669::BIGINT, 'Profesores como él definitivamente no representan la escuela de ATI. La calificación de todas las asignaciones se basa mayormente en una redacción "impecable"; es extremadamente estricto en la forma de evaluar. Realiza quices sorpresa y tareas "morales" que no aportan nada.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2026-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'ca7a9ae273e6c453e57519810050eb40ca01adbf06e55637879ba85e0f217463'::TEXT, ARRAY[2528, 2521]::BIGINT[]),
    (669::BIGINT, 'Definitivamente el profesor más repugnante de ATI. Tiene a sus preferidos y a los que no, busca humillarlos durante todo el semestre. Los asistentes califican DEMASIADO duro, no importa si usted sigue las instrucciones al pie de la letra, siempre van a encontrar algo malo. NO lo recomiendo.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Clases largas']::TEXT[], '2026-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'dff8db0ffa4af4e1d998ad199662aa95f1b005118a27a7ef31dc1f841ad884c3'::TEXT, ARRAY[2520, 2521, 2528]::BIGINT[]),
    (669::BIGINT, 'Explica demasiado bien, a veces puede ser un poco irritante, pero es muy buen profe. Sus asistentes califican duro y los quizzes son sorpresa y da poco tiempo. Se aprende demasiado con él, cosas que sirven para toda la carrera y prepara MUY BIEN para AP.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2026-05-15T00:00:00+00:00'::TIMESTAMPTZ, 'ffc9009b53da0fe1f057eb40f82479f7ea45c41f8c48c471a7ceb543a3cb4f55'::TEXT, ARRAY[2520]::BIGINT[]),
    (669::BIGINT, 'En general este profe es bueno, me cae mal pero no puedo negar que explica muy bien y se le entiende todo, da buenos ejemplos y hace actividades para mantener la atención en la clase, todo es grupal, hace exámenes larguísimos y no avisa cuando hay quiz. A sepa que va a leer MUCHO, y en ingles.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2026-02-11T00:00:00+00:00'::TIMESTAMPTZ, 'ee2b69599a7d79cc361d119c160a0aea2aeb5d97f368081f59b6dc886d37cc7a'::TEXT, ARRAY[2520]::BIGINT[]),
    (669::BIGINT, 'Es un excelente profesor, si realmente desea aprender, matricule con él. Todos los trabajos son grupales, así que consiga un buen equipo, SIGA las indicaciones que el o las asistentes dejen, porque califican duro, pero si usted sigue las indicaciones, le va a ir bien.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '157e827287ae64927f56f2fdf880f062dbb6626c850828ed5662a84152247f6a'::TEXT, ARRAY[2520]::BIGINT[]),
    (669::BIGINT, 'Es importante al matricular con este profe que sepan que sus asistentes se dedican a calificar lo peor que puedan y a no ayudar en nada, el profe es buena gente con los que quiere y su forma de aclarar las instrucciones a realizar es pesima. no lleven el curso, si pueden optar por otra opcion hagalo'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Deja trabajos largos']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, '40a53ec003b31a681df46c9ac0456045b294e509157c2646094dbae5467b7e2f'::TEXT, ARRAY[2520]::BIGINT[]),
    (669::BIGINT, 'Primero que todo, si puede con otro profe que no sea sonia ni este, haganse el favor de matricular con el porque va a ser mas facil, segundo, realmente no es mal profe, sus explicaciones no son malas, el problema esque es totalmente irracional, exige respeto pero no lo da. Mucho cuidado con el.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Deja trabajos largos']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'a4b2807db4d09a96f54b36493826dcdafc27866d6ce498dd33f079217f4e01c4'::TEXT, ARRAY[2520]::BIGINT[]),
    (669::BIGINT, 'No lo recomiendo, primero tiene una forma de contestarle a uno bien repugnante, parece que el cronograma que el mismo hace lo tiene solamente de decoración, muchas veces ni lo respeta. Aplica quices cada que él quiere. Califica duro, las asistentes igual, parecen que no tienen nada mejor que hacer.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2025-10-20T00:00:00+00:00'::TIMESTAMPTZ, '5ee2f24d09b20ba5be92e4d4205b6bab0b9edbcca6c4f983e88f33006a393868'::TEXT, ARRAY[2521]::BIGINT[]),
    (669::BIGINT, 'Terrible'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-10-13T00:00:00+00:00'::TIMESTAMPTZ, '68c51b460442d19b7ce34777da43720bc00f8fb3bf3b0dc1d561a2dd6336813b'::TEXT, ARRAY[2520]::BIGINT[]),
    (669::BIGINT, 'Es un profesor que hace las clases como una dictadura, ve a los estudiantes como menos y no les tiene respeto pero espera que nosotros sí. Es irracional e innecesariamente estricto y difícil. Es mejor que Sonia pero solo relativamente porque igual es muy malo.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'f2d3b5c1a42ae82afe86375623e5137e95bb0046bb10ba76738f8ec523a65e44'::TEXT, ARRAY[2520]::BIGINT[]),
    (669::BIGINT, 'En este curso experimenté un sube y baja de emociones... Me gusta cómo el profesor explica y los ejemplos que da basados en su experiencia, pero las evaluaciones son bastante matadoras. Si es necesario estudiar bastante para los examenes.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2025-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'be24c7d4bad7c5c197f03d59cb00e88ce98dd10e8a1d6ff2883a9a5fcfc9b67b'::TEXT, ARRAY[2586]::BIGINT[]),
    (669::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2025-05-03T00:00:00+00:00'::TIMESTAMPTZ, '9ea96f7462f50e14fbc9bf7965ff7c2e42b7ee36b29a14314bcc32fcd7485b91'::TEXT, ARRAY[2586]::BIGINT[]),
    (669::BIGINT, 'Sí, es mejor él que Sonia. Pero las rúbricas e instrucciones de los trabajos son demasiado ambiguas y malas. Tanto él como asistentes califican demasiado duro. Pregunte mucho y vaya a hora de consulta.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2025-02-18T00:00:00+00:00'::TIMESTAMPTZ, '1f22c403a316c8fd2c26b4984da42a9d551d7047b5edc5be14911753aac58516'::TEXT, ARRAY[2520]::BIGINT[]),
    (669::BIGINT, 'Tengo mucho que decir de este curso, es cierto da mejor las clases que Sonia sí, pero el eleva más la evaluación califica muy dura el primer examen fue mortal, muy duro, el segundo examen fue sobreviva el mejor quite puntos, vea como los otros se quedan, juegos de hambre le dicen, rudisimo ese mae'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'afcca0b87eb7d879c539d1ce149246a4216db585916ab37fbcb9bbbcdf7cb1e1'::TEXT, ARRAY[2585]::BIGINT[]),
    (669::BIGINT, 'Es el mejor profe de peti hasta ahora en términos de temas y claridad de temas, se aprende mucho y es muy objetivo. Sin embargo, sus exámenes son innecesariamente difíciles, cronometrados y en equipo. El curso termina pareciendo los juego del hambre y la modalidad facilita a peleas entre equipos.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd98af26c6834a1eff7e128e336ed18d1015a614b07c6fdbdbd6d58bd3bc4abea'::TEXT, ARRAY[2585]::BIGINT[]),
    (669::BIGINT, 'Hace las clases amenas y es entretenido pero es muy estricto. Uno aprende bastante… Deja algunas presentaciones en inglés que son “morales”, y es bastante crítico con las exposiciones que se deben hacer, es bastante necio con que deben hacerse exposiciones impecables.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2024-03-28T00:00:00+00:00'::TIMESTAMPTZ, '2aa8b74132830209783ce5f8137ca7eadb3baf3c0f8d9723ed53bbaa1ebba360'::TEXT, ARRAY[2528, 2521]::BIGINT[]),
    (669::BIGINT, 'Es un argollero y no explica bien, califica como si fuera buen profe. se nota que entró de profe por la misma argolla que maneja con Sonia.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2024-03-24T00:00:00+00:00'::TIMESTAMPTZ, '13124185d9cc3409c391fd353bb1f1ed0bcca680f500ae1eebe59d7a0c568845'::TEXT, ARRAY[2528, 2521]::BIGINT[]),
    (669::BIGINT, 'El mae es bueno sabe de lo que habla, el si lo va a tratar como un ser humano con derechos en comparacion con la otra profesora que lo trata como animal de matadero. Es un perfeccionista con lo que uno hace pero eso le ayuda a uno para crecer futuro ATI, pero el da la misma perfeccion en la clase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2024-02-15T00:00:00+00:00'::TIMESTAMPTZ, '4751078917ffb66b8b6faec2c87586845edc3f72f77c81f6eb2751d888ab839d'::TEXT, ARRAY[2528]::BIGINT[]),
    (669::BIGINT, 'Es un gran profesor, es estricto pero muy buena persona, exige excelencia y él proporciona esa excelencia en sus clases, definitivamente volvería a llevar con él.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2023-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'c14b324a9f5dfbfd056e86e6ee30edcafe15c3c818c911743b9538ceb88e058a'::TEXT, ARRAY[2521]::BIGINT[]),
    (669::BIGINT, 'Excelente profesor, enseña super bien y a pesar de haber muchas tareas se aprende demasiado con él. Super recomendado'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '2fc768284816cb1e08eba2cd0f068a2ea553f9fc274eaaae8d259d28affa2c3b'::TEXT, ARRAY[2521]::BIGINT[]),
    (669::BIGINT, 'Excelente profe, un poco duro pero es por el tipo de curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2023-05-29T00:00:00+00:00'::TIMESTAMPTZ, '4a14fcb0a7e1f9e8a8e252c2605c24b0f77e556b11a8a8f19d52b125054dd714'::TEXT, ARRAY[2521]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
